create or replace function public.jf_workspace_page(target_shop uuid,entity text,filters jsonb default '{}',page_number integer default 0) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;st text:=coalesce(filters->>'status','all');search text:=trim(coalesce(filters->>'search',''));agent_id uuid:=nullif(filters->>'agent_id','')::uuid;
begin
 if page_number is null or page_number<0 or length(search)>200 then raise exception 'Invalid page filter.';end if;
 if entity='customers' then
  with base as materialized(select c.*,f.status followup_status,f.call_outcome,f.callback_at,(buyers.customer_id is not null) has_confirmed from public.jf_customers c left join public.jf_followups f on f.shop_id=c.shop_id and f.customer_id=c.id left join (select distinct x.customer_id from public.jf_orders x where x.shop_id=target_shop and x.archived_at is null and x.status not in('draft','cancelled')) buyers on buyers.customer_id=c.id where c.shop_id=target_shop and c.archived_at is null and (agent_id is null or c.assigned_membership_id=agent_id)
   and (coalesce(filters->>'source','')='' or lower(c.source)=lower(filters->>'source')) and (coalesce(filters->>'tag','')='' or c.unassignment_tag=filters->>'tag') and (coalesce(filters->>'response','')='' or f.call_outcome=lower(filters->>'response')) and (coalesce(filters->>'call','')='' or lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')) and (search='' or c.full_name ilike '%'||search||'%' or c.phone ilike '%'||search||'%')),c as(select * from base c where (st='confirmed' and c.has_confirmed or st='attempted' and c.call_outcome is not null and c.call_outcome<>'not_attempted' or st='failed' and c.call_outcome is not null and c.call_outcome<>'not_attempted' and not c.has_confirmed or lower(replace(c.workflow_label,' ','_'))=st or st in('no_answer','busy') and c.call_outcome=st or st='all' or st='unassigned' and c.assigned_membership_id is null or st='assigned' and c.assigned_membership_id is not null or st='permanent' and c.permanent or st='completed' and c.followup_status='completed' or st='pending' and coalesce(c.followup_status,'pending') in ('pending','callback') or st='cancelled' and c.followup_status='cancelled' or st='connected' and c.call_outcome in ('connected','positive','negative','intermediate') or st='not_connected' and c.call_outcome in ('not_connected','no_answer','busy') or st='not_attempted' and (c.call_outcome is null or c.call_outcome='not_attempted') or st in ('positive','negative','intermediate') and c.call_outcome=st or st='callback' and c.followup_status='callback' or st='callbacks' and c.followup_status='callback' and c.callback_at<=now() or st='buyers' and c.followup_status='completed' and c.has_confirmed))
  select jsonb_build_object('counts',coalesce((select jsonb_object_agg(k,n) from(select lower(replace(workflow_label,' ','_')) k,count(*) n from base where nullif(workflow_label,'') is not null group by 1) labels),'{}'::jsonb)||(select jsonb_build_object('all',count(*) filter(where true),'assigned',count(*) filter(where assigned_membership_id is not null),'unassigned',count(*) filter(where assigned_membership_id is null),'completed',count(*) filter(where followup_status='completed'),'pending',count(*) filter(where coalesce(followup_status,'pending') in('pending','callback')),'cancelled',count(*) filter(where followup_status='cancelled'),'permanent',count(*) filter(where permanent),'connected',count(*) filter(where call_outcome in('connected','positive','negative','intermediate')),'not_connected',count(*) filter(where call_outcome in('not_connected','no_answer','busy')),'not_attempted',count(*) filter(where call_outcome is null or call_outcome='not_attempted'),'attempted',count(*) filter(where call_outcome is not null and call_outcome<>'not_attempted'),'confirmed',count(*) filter(where has_confirmed),'failed',count(*) filter(where call_outcome is not null and call_outcome<>'not_attempted' and not has_confirmed),'buyers',count(*) filter(where followup_status='completed' and has_confirmed),'callback',count(*) filter(where followup_status='callback'),'callbacks',count(*) filter(where followup_status='callback' and callback_at<=now()),'positive',count(*) filter(where call_outcome='positive'),'negative',count(*) filter(where call_outcome='negative'),'intermediate',count(*) filter(where call_outcome='intermediate'),'no_answer',count(*) filter(where call_outcome='no_answer'),'busy',count(*) filter(where call_outcome='busy')) from base),'total',(select count(*) from c),'rows',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('order_date',coalesce((select coalesce(h.details->>'ordered_at',h.details->>'order_date',h.details->>'created_at') from public.jf_order_history h where h.shop_id=target_shop and h.customer_id=p.id order by h.updated_at desc,h.id limit 1),(select o.created_at::text from public.jf_orders o where o.shop_id=target_shop and o.customer_id=p.id and o.archived_at is null order by o.created_at desc,o.id limit 1)),'latest_note',(select n.body from public.jf_notes n where n.shop_id=target_shop and n.customer_id=p.id order by n.created_at desc,n.id desc limit 1),'order_count',(select count(*) from public.jf_orders z where z.shop_id=target_shop and z.customer_id=p.id and z.archived_at is null))) from(select * from c order by updated_at desc,id limit 50 offset page_number::bigint*50) p),'[]')) into result;
 elsif entity='orders' then
  with live as materialized(select o.* from public.jf_orders o where o.shop_id=target_shop and o.archived_at is null and (agent_id is null or o.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or o.created_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or o.created_at<(filters->>'report_end')::timestamptz) and (coalesce(filters->>'source','')='' or case when lower(o.source) in('website','facebook','whatsapp') then lower(o.source) else 'other' end=filters->>'source') and (nullif(filters->>'product_id','') is null or exists(select 1 from public.jf_order_items i where i.shop_id=target_shop and i.order_id=o.id and i.product_id=(filters->>'product_id')::uuid)) and (coalesce(filters->>'tag','')='' or exists(select 1 from public.jf_customers c where c.shop_id=target_shop and c.id=o.customer_id and c.unassignment_tag=filters->>'tag')) and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')))) and (search='' or o.order_number ilike '%'||search||'%' or o.recipient_name ilike '%'||search||'%' or o.recipient_phone ilike '%'||search||'%')),history as materialized(select h.id,h.external_id order_number,c.full_name recipient_name,c.phone recipient_phone,c.address delivery_address,c.source,c.assigned_membership_id,h.customer_id,h.updated_at created_at,h.updated_at,'imported'::text status,true is_imported,h.details,case when coalesce(h.details->>'total','') ~ '^[0-9]+([.][0-9]+)?$' then (h.details->>'total')::numeric else 0 end total
   from public.jf_order_history h join public.jf_customers c on c.shop_id=h.shop_id and c.id=h.customer_id where h.shop_id=target_shop and c.archived_at is null and (agent_id is null or c.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or h.updated_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or h.updated_at<(filters->>'report_end')::timestamptz)
   and (coalesce(filters->>'source','')='' or lower(c.source)=lower(filters->>'source')) and (coalesce(filters->>'tag','')='' or c.unassignment_tag=filters->>'tag') and nullif(filters->>'product_id','') is null and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=c.id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=c.id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy'))))
   and (search='' or h.external_id ilike '%'||search||'%' or c.full_name ilike '%'||search||'%' or c.phone ilike '%'||search||'%')),entries as materialized(select to_jsonb(l)||jsonb_build_object('is_imported',false) entry,l.id,l.created_at from live l union all select to_jsonb(h) entry,h.id,h.created_at from history h where not exists(select 1 from live l where l.order_number=h.order_number)),matching as(select * from entries where st='all' or st='imported' and coalesce((entry->>'is_imported')::boolean,false) or st='confirmed' and entry->>'status' not in('draft','cancelled','imported') or st='ready_to_book' and entry->>'status' in('confirmed','ready_to_book') or st not in('all','imported','confirmed','ready_to_book') and entry->>'status'=st)
  select jsonb_build_object('counts',(select jsonb_build_object('all',count(*) filter(where true),'imported',count(*) filter(where coalesce((entry->>'is_imported')::boolean,false)),'confirmed',count(*) filter(where entry->>'status' not in('draft','cancelled','imported')),'ready_to_book',count(*) filter(where entry->>'status' in('confirmed','ready_to_book')),'draft',count(*) filter(where entry->>'status'='draft'),'booked',count(*) filter(where entry->>'status'='booked'),'in_transit',count(*) filter(where entry->>'status'='in_transit'),'delivered',count(*) filter(where entry->>'status'='delivered'),'partial_delivery',count(*) filter(where entry->>'status'='partial_delivery'),'returned',count(*) filter(where entry->>'status'='returned'),'cancelled',count(*) filter(where entry->>'status'='cancelled'),'exchange',count(*) filter(where entry->>'status'='exchange'),'replacement',count(*) filter(where entry->>'status'='replacement')) from entries),'total',(select count(*) from matching),'rows',coalesce((select jsonb_agg(entry order by created_at desc,id) from(select * from matching order by created_at desc,id limit 50 offset page_number::bigint*50)p),'[]'::jsonb)) into result;
 else raise exception 'Choose customers or orders.';end if;
 return result;
end $$;

create or replace function public.jf_agent_report(target_shop uuid,target_agent uuid default null,report_start timestamptz default null,report_end timestamptz default null) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb; filters jsonb:=jsonb_build_object('report_start',report_start,'report_end',report_end);agent_id uuid:=target_agent;search text:='';
begin
 if not jioflow_private.manages_shop(target_shop) then raise exception 'Agent reporting access denied.' using errcode='42501';end if;
 if target_agent is not null and not exists(select 1 from public.jf_memberships where id=target_agent and shop_id=target_shop and role='agent' and status<>'removed') then raise exception 'Agent not found in this business.' using errcode='42501';end if;
 if report_start is not null and report_end is not null and report_start>=report_end then raise exception 'Invalid reporting period.';end if;
with live as materialized(select o.* from public.jf_orders o where o.shop_id=target_shop and o.archived_at is null and (agent_id is null or o.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or o.created_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or o.created_at<(filters->>'report_end')::timestamptz) and (coalesce(filters->>'source','')='' or case when lower(o.source) in('website','facebook','whatsapp') then lower(o.source) else 'other' end=filters->>'source') and (nullif(filters->>'product_id','') is null or exists(select 1 from public.jf_order_items i where i.shop_id=target_shop and i.order_id=o.id and i.product_id=(filters->>'product_id')::uuid)) and (coalesce(filters->>'tag','')='' or exists(select 1 from public.jf_customers c where c.shop_id=target_shop and c.id=o.customer_id and c.unassignment_tag=filters->>'tag')) and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')))) and (search='' or o.order_number ilike '%'||search||'%' or o.recipient_name ilike '%'||search||'%' or o.recipient_phone ilike '%'||search||'%')),history as materialized(select h.id,h.external_id order_number,c.full_name recipient_name,c.phone recipient_phone,c.address delivery_address,c.source,c.assigned_membership_id,h.customer_id,h.updated_at created_at,h.updated_at,'imported'::text status,true is_imported,h.details,case when coalesce(h.details->>'total','') ~ '^[0-9]+([.][0-9]+)?$' then (h.details->>'total')::numeric else 0 end total
   from public.jf_order_history h join public.jf_customers c on c.shop_id=h.shop_id and c.id=h.customer_id where h.shop_id=target_shop and c.archived_at is null and (agent_id is null or c.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or h.updated_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or h.updated_at<(filters->>'report_end')::timestamptz)
   and (coalesce(filters->>'source','')='' or lower(c.source)=lower(filters->>'source')) and (coalesce(filters->>'tag','')='' or c.unassignment_tag=filters->>'tag') and nullif(filters->>'product_id','') is null and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=c.id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=c.id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy'))))
   and (search='' or h.external_id ilike '%'||search||'%' or c.full_name ilike '%'||search||'%' or c.phone ilike '%'||search||'%')),orders as materialized(select l.customer_id,l.assigned_membership_id,l.status,l.total,l.created_at,false is_imported from live l union all select h.customer_id,h.assigned_membership_id,h.status,h.total,h.created_at,true is_imported from history h where not exists(select 1 from live l where l.order_number=h.order_number)),
 c as(select c.assigned_membership_id id,count(*) filter(where true) assigned,count(*) filter(where f.status='completed') completed,count(*) filter(where coalesce(f.status,'pending') in('pending','callback')) pending,count(*) filter(where f.status='cancelled') cancelled,count(*) filter(where f.call_outcome is not null and f.call_outcome<>'not_attempted') attempted,count(*) filter(where f.call_outcome is null or f.call_outcome='not_attempted') not_attempted,count(*) filter(where f.call_outcome in('connected','positive','negative','intermediate')) connected,count(*) filter(where f.call_outcome in('not_connected','no_answer','busy')) not_connected,count(*) filter(where f.status='callback' and f.callback_at<=now()) callbacks,count(*) filter(where c.permanent) permanent,count(*) filter(where f.call_outcome='positive') positive,count(*) filter(where f.call_outcome='negative') negative,count(*) filter(where f.call_outcome='intermediate') intermediate,count(*) filter(where f.status='completed' and exists(select 1 from orders o where o.customer_id=c.id and o.status not in('draft','cancelled','imported'))) buyers from public.jf_customers c left join public.jf_followups f on f.shop_id=c.shop_id and f.customer_id=c.id where c.shop_id=target_shop and c.archived_at is null group by c.assigned_membership_id),
 o as(select assigned_membership_id id,count(*) filter(where true) orders,count(*) filter(where status not in('draft','cancelled','imported')) confirmed,count(*) filter(where status='delivered') delivered,count(*) filter(where status='returned') returned,count(*) filter(where status='cancelled') cancelled_orders,count(*) filter(where status='draft') draft,count(*) filter(where status='booked') booked,count(*) filter(where status='in_transit') in_transit,count(*) filter(where status in('confirmed','ready_to_book')) ready_to_book,count(*) filter(where is_imported) imported,coalesce(sum(total) filter(where status not in('draft','cancelled','imported')),0) revenue from orders group by assigned_membership_id)
 select jsonb_build_object('agents',coalesce(jsonb_agg(jsonb_build_object('id',m.id,'user_id',m.user_id,'name',p.full_name,'email',p.email,'code',p.user_code,'avatar',p.avatar_path,'active',p.active and m.status='active','assigned',coalesce(c.assigned,0),'completed',coalesce(c.completed,0),'pending',coalesce(c.pending,0),'cancelled',coalesce(c.cancelled,0),'attempted',coalesce(c.attempted,0),'not_attempted',coalesce(c.not_attempted,0),'connected',coalesce(c.connected,0),'not_connected',coalesce(c.not_connected,0),'callbacks',coalesce(c.callbacks,0),'permanent',coalesce(c.permanent,0),'positive',coalesce(c.positive,0),'negative',coalesce(c.negative,0),'intermediate',coalesce(c.intermediate,0),'orders',coalesce(o.orders,0),'confirmed',coalesce(o.confirmed,0),'delivered',coalesce(o.delivered,0),'returned',coalesce(o.returned,0),'cancelled_orders',coalesce(o.cancelled_orders,0),'draft',coalesce(o.draft,0),'booked',coalesce(o.booked,0),'in_transit',coalesce(o.in_transit,0),'ready_to_book',coalesce(o.ready_to_book,0),'imported',coalesce(o.imported,0),'revenue',coalesce(o.revenue,0),'buyers',coalesce(c.buyers,0),'purchase_rate',case when coalesce(c.completed,0)=0 then 0 else 100.0*c.buyers/c.completed end) order by p.full_name),'[]'::jsonb)) into result from public.jf_memberships m join public.jf_profiles p on p.id=m.user_id left join c on c.id=m.id left join o on o.id=m.id where m.shop_id=target_shop and m.role='agent' and m.status<>'removed' and p.deleted_at is null and (target_agent is null or m.id=target_agent);
 if target_agent is not null then
 result:=result||jsonb_build_object('activity',coalesce((select jsonb_agg(to_jsonb(e) order by e.at desc) from(
 select * from(select 'followup' kind,e.created_at at,e.outcome status,e.note,c.id customer_id,c.full_name customer_name,c.phone from public.jf_followup_events e join public.jf_followups f on f.shop_id=e.shop_id and f.id=e.followup_id join public.jf_customers c on c.shop_id=f.shop_id and c.id=f.customer_id where e.shop_id=target_shop and e.actor_id=(select user_id from public.jf_memberships where id=target_agent) and (report_start is null or e.created_at>=report_start) and (report_end is null or e.created_at<report_end) order by e.created_at desc limit 30) f
 union all
 select * from(select 'order' kind,e.created_at at,e.status,e.note,o.customer_id,o.recipient_name customer_name,o.recipient_phone phone from public.jf_order_events e join public.jf_orders o on o.shop_id=e.shop_id and o.id=e.order_id where e.shop_id=target_shop and e.actor_id=(select user_id from public.jf_memberships where id=target_agent) and (report_start is null or e.created_at>=report_start) and (report_end is null or e.created_at<report_end) order by e.created_at desc limit 30) o
 order by at desc limit 30)e),'[]'::jsonb));end if;
 return result;
end $$;
insert into public.jf_schema_versions(version) values('028_import_manual_workflow') on conflict do nothing;
commit;


-- Apply after 028. No historical rows are deleted.
begin;
do $$begin if not exists(select 1 from public.jf_schema_versions where version='028_import_manual_workflow') then raise exception 'Apply migration 028 first.';end if;end$$;
create or replace function public.jf_workspace_page(target_shop uuid,entity text,filters jsonb default '{}',page_number integer default 0) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;st text:=coalesce(filters->>'status','all');search text:=trim(coalesce(filters->>'search',''));agent_id uuid:=nullif(filters->>'agent_id','')::uuid;
begin
 if page_number is null or page_number<0 or length(search)>200 then raise exception 'Invalid page filter.';end if;
 if entity='customers' then
  with base as materialized(select c.*,f.status followup_status,f.call_outcome,f.callback_at,(buyers.customer_id is not null) has_confirmed from public.jf_customers c left join public.jf_followups f on f.shop_id=c.shop_id and f.customer_id=c.id left join (select distinct x.customer_id from public.jf_orders x where x.shop_id=target_shop and x.archived_at is null and x.status not in('draft','cancelled')) buyers on buyers.customer_id=c.id where c.shop_id=target_shop and c.archived_at is null and (agent_id is null or c.assigned_membership_id=agent_id)
   and (coalesce(filters->>'source','')='' or lower(c.source)=lower(filters->>'source')) and (coalesce(filters->>'tag','')='' or c.unassignment_tag=filters->>'tag') and (coalesce(filters->>'response','')='' or f.call_outcome=lower(filters->>'response')) and (coalesce(filters->>'call','')='' or lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')) and (search='' or c.full_name ilike '%'||search||'%' or c.phone ilike '%'||search||'%')),c as(select * from base c where (st='confirmed' and c.has_confirmed or st='attempted' and c.call_outcome is not null and c.call_outcome<>'not_attempted' or st='failed' and c.call_outcome is not null and c.call_outcome<>'not_attempted' and not c.has_confirmed or lower(replace(c.workflow_label,' ','_'))=st or st in('no_answer','busy') and c.call_outcome=st or st='all' or st='unassigned' and c.assigned_membership_id is null or st='assigned' and c.assigned_membership_id is not null or st='permanent' and c.permanent or st='completed' and c.followup_status='completed' or st='pending' and coalesce(c.followup_status,'pending') in ('pending','callback') or st='cancelled' and c.followup_status='cancelled' or st='connected' and c.call_outcome in ('connected','positive','negative','intermediate') or st='not_connected' and c.call_outcome in ('not_connected','no_answer','busy') or st='not_attempted' and (c.call_outcome is null or c.call_outcome='not_attempted') or st in ('positive','negative','intermediate') and c.call_outcome=st or st='callback' and c.followup_status='callback' or st='callbacks' and c.followup_status='callback' and c.callback_at<=now() or st='buyers' and c.followup_status='completed' and c.has_confirmed))
  select jsonb_build_object('counts',coalesce((select jsonb_object_agg(k,n) from(select lower(replace(workflow_label,' ','_')) k,count(*) n from base where nullif(workflow_label,'') is not null group by 1) labels),'{}'::jsonb)||(select jsonb_build_object('all',count(*) filter(where true),'assigned',count(*) filter(where assigned_membership_id is not null),'unassigned',count(*) filter(where assigned_membership_id is null),'completed',count(*) filter(where followup_status='completed'),'pending',count(*) filter(where coalesce(followup_status,'pending') in('pending','callback')),'cancelled',count(*) filter(where followup_status='cancelled'),'permanent',count(*) filter(where permanent),'connected',count(*) filter(where call_outcome in('connected','positive','negative','intermediate')),'not_connected',count(*) filter(where call_outcome in('not_connected','no_answer','busy')),'not_attempted',count(*) filter(where call_outcome is null or call_outcome='not_attempted'),'attempted',count(*) filter(where call_outcome is not null and call_outcome<>'not_attempted'),'confirmed',count(*) filter(where has_confirmed),'failed',count(*) filter(where call_outcome is not null and call_outcome<>'not_attempted' and not has_confirmed),'buyers',count(*) filter(where followup_status='completed' and has_confirmed),'callback',count(*) filter(where followup_status='callback'),'callbacks',count(*) filter(where followup_status='callback' and callback_at<=now()),'positive',count(*) filter(where call_outcome='positive'),'negative',count(*) filter(where call_outcome='negative'),'intermediate',count(*) filter(where call_outcome='intermediate'),'no_answer',count(*) filter(where call_outcome='no_answer'),'busy',count(*) filter(where call_outcome='busy')) from base),'total',(select count(*) from c),'rows',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('order_date',coalesce((select coalesce(h.details->>'ordered_at',h.details->>'order_date',h.details->>'created_at') from public.jf_order_history h where h.shop_id=target_shop and h.customer_id=p.id order by h.updated_at desc,h.id limit 1),(select o.created_at::text from public.jf_orders o where o.shop_id=target_shop and o.customer_id=p.id and o.archived_at is null order by o.created_at desc,o.id limit 1)),'latest_note',(select n.body from public.jf_notes n where n.shop_id=target_shop and n.customer_id=p.id order by n.created_at desc,n.id desc limit 1),'order_count',(select count(*) from public.jf_orders z where z.shop_id=target_shop and z.customer_id=p.id and z.archived_at is null))) from(select * from c order by updated_at desc,id limit 50 offset page_number::bigint*50) p),'[]')) into result;
 elsif entity='orders' then
  with live as materialized(select o.* from public.jf_orders o where o.shop_id=target_shop and o.archived_at is null and (agent_id is null or o.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or o.created_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or o.created_at<(filters->>'report_end')::timestamptz) and (coalesce(filters->>'source','')='' or case when lower(o.source) in('website','facebook','whatsapp') then lower(o.source) else 'other' end=filters->>'source') and (nullif(filters->>'product_id','') is null or exists(select 1 from public.jf_order_items i where i.shop_id=target_shop and i.order_id=o.id and i.product_id=(filters->>'product_id')::uuid)) and (coalesce(filters->>'tag','')='' or exists(select 1 from public.jf_customers c where c.shop_id=target_shop and c.id=o.customer_id and c.unassignment_tag=filters->>'tag')) and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')))) and (search='' or o.order_number ilike '%'||search||'%' or o.recipient_name ilike '%'||search||'%' or o.recipient_phone ilike '%'||search||'%')),entries as materialized(select to_jsonb(l)||jsonb_build_object('is_imported',false) entry,l.id,l.created_at from live l),matching as(select * from entries where st='all' or st='imported' and coalesce((entry->>'is_imported')::boolean,false) or st='confirmed' and entry->>'status' not in('draft','cancelled','imported') or st='ready_to_book' and entry->>'status' in('confirmed','ready_to_book') or st not in('all','imported','confirmed','ready_to_book') and entry->>'status'=st)
  select jsonb_build_object('counts',(select jsonb_build_object('all',count(*) filter(where true),'imported',count(*) filter(where coalesce((entry->>'is_imported')::boolean,false)),'confirmed',count(*) filter(where entry->>'status' not in('draft','cancelled','imported')),'ready_to_book',count(*) filter(where entry->>'status' in('confirmed','ready_to_book')),'draft',count(*) filter(where entry->>'status'='draft'),'booked',count(*) filter(where entry->>'status'='booked'),'in_transit',count(*) filter(where entry->>'status'='in_transit'),'delivered',count(*) filter(where entry->>'status'='delivered'),'partial_delivery',count(*) filter(where entry->>'status'='partial_delivery'),'returned',count(*) filter(where entry->>'status'='returned'),'cancelled',count(*) filter(where entry->>'status'='cancelled'),'exchange',count(*) filter(where entry->>'status'='exchange'),'replacement',count(*) filter(where entry->>'status'='replacement')) from entries),'total',(select count(*) from matching),'rows',coalesce((select jsonb_agg(entry order by created_at desc,id) from(select * from matching order by created_at desc,id limit 50 offset page_number::bigint*50)p),'[]'::jsonb)) into result;
 else raise exception 'Choose customers or orders.';end if;
 return result;
end $$;

create or replace function public.jf_agent_report(target_shop uuid,target_agent uuid default null,report_start timestamptz default null,report_end timestamptz default null) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb; filters jsonb:=jsonb_build_object('report_start',report_start,'report_end',report_end);agent_id uuid:=target_agent;search text:='';
begin
 if not jioflow_private.manages_shop(target_shop) then raise exception 'Agent reporting access denied.' using errcode='42501';end if;
 if target_agent is not null and not exists(select 1 from public.jf_memberships where id=target_agent and shop_id=target_shop and role='agent' and status<>'removed') then raise exception 'Agent not found in this business.' using errcode='42501';end if;
 if report_start is not null and report_end is not null and report_start>=report_end then raise exception 'Invalid reporting period.';end if;
with live as materialized(select o.* from public.jf_orders o where o.shop_id=target_shop and o.archived_at is null and (agent_id is null or o.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or o.created_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or o.created_at<(filters->>'report_end')::timestamptz) and (coalesce(filters->>'source','')='' or case when lower(o.source) in('website','facebook','whatsapp') then lower(o.source) else 'other' end=filters->>'source') and (nullif(filters->>'product_id','') is null or exists(select 1 from public.jf_order_items i where i.shop_id=target_shop and i.order_id=o.id and i.product_id=(filters->>'product_id')::uuid)) and (coalesce(filters->>'tag','')='' or exists(select 1 from public.jf_customers c where c.shop_id=target_shop and c.id=o.customer_id and c.unassignment_tag=filters->>'tag')) and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')))) and (search='' or o.order_number ilike '%'||search||'%' or o.recipient_name ilike '%'||search||'%' or o.recipient_phone ilike '%'||search||'%')),orders as materialized(select l.customer_id,l.assigned_membership_id,l.status,l.total,l.created_at,false is_imported from live l),
 c as(select c.assigned_membership_id id,count(*) filter(where true) assigned,count(*) filter(where f.status='completed') completed,count(*) filter(where coalesce(f.status,'pending') in('pending','callback')) pending,count(*) filter(where f.status='cancelled') cancelled,count(*) filter(where f.call_outcome is not null and f.call_outcome<>'not_attempted') attempted,count(*) filter(where f.call_outcome is null or f.call_outcome='not_attempted') not_attempted,count(*) filter(where f.call_outcome in('connected','positive','negative','intermediate')) connected,count(*) filter(where f.call_outcome in('not_connected','no_answer','busy')) not_connected,count(*) filter(where f.status='callback' and f.callback_at<=now()) callbacks,count(*) filter(where c.permanent) permanent,count(*) filter(where f.call_outcome='positive') positive,count(*) filter(where f.call_outcome='negative') negative,count(*) filter(where f.call_outcome='intermediate') intermediate,count(*) filter(where f.status='completed' and exists(select 1 from orders o where o.customer_id=c.id and o.status not in('draft','cancelled','imported'))) buyers from public.jf_customers c left join public.jf_followups f on f.shop_id=c.shop_id and f.customer_id=c.id where c.shop_id=target_shop and c.archived_at is null group by c.assigned_membership_id),
 o as(select assigned_membership_id id,count(*) filter(where true) orders,count(*) filter(where status not in('draft','cancelled','imported')) confirmed,count(*) filter(where status='delivered') delivered,count(*) filter(where status='returned') returned,count(*) filter(where status='cancelled') cancelled_orders,count(*) filter(where status='draft') draft,count(*) filter(where status='booked') booked,count(*) filter(where status='in_transit') in_transit,count(*) filter(where status in('confirmed','ready_to_book')) ready_to_book,count(*) filter(where is_imported) imported,coalesce(sum(total) filter(where status not in('draft','cancelled','imported')),0) revenue from orders group by assigned_membership_id)
 select jsonb_build_object('agents',coalesce(jsonb_agg(jsonb_build_object('id',m.id,'user_id',m.user_id,'name',p.full_name,'email',p.email,'code',p.user_code,'avatar',p.avatar_path,'active',p.active and m.status='active','assigned',coalesce(c.assigned,0),'completed',coalesce(c.completed,0),'pending',coalesce(c.pending,0),'cancelled',coalesce(c.cancelled,0),'attempted',coalesce(c.attempted,0),'not_attempted',coalesce(c.not_attempted,0),'connected',coalesce(c.connected,0),'not_connected',coalesce(c.not_connected,0),'callbacks',coalesce(c.callbacks,0),'permanent',coalesce(c.permanent,0),'positive',coalesce(c.positive,0),'negative',coalesce(c.negative,0),'intermediate',coalesce(c.intermediate,0),'orders',coalesce(o.orders,0),'confirmed',coalesce(o.confirmed,0),'delivered',coalesce(o.delivered,0),'returned',coalesce(o.returned,0),'cancelled_orders',coalesce(o.cancelled_orders,0),'draft',coalesce(o.draft,0),'booked',coalesce(o.booked,0),'in_transit',coalesce(o.in_transit,0),'ready_to_book',coalesce(o.ready_to_book,0),'imported',coalesce(o.imported,0),'revenue',coalesce(o.revenue,0),'buyers',coalesce(c.buyers,0),'purchase_rate',case when coalesce(c.completed,0)=0 then 0 else 100.0*c.buyers/c.completed end) order by p.full_name),'[]'::jsonb)) into result from public.jf_memberships m join public.jf_profiles p on p.id=m.user_id left join c on c.id=m.id left join o on o.id=m.id where m.shop_id=target_shop and m.role='agent' and m.status<>'removed' and p.deleted_at is null and (target_agent is null or m.id=target_agent);
 if target_agent is not null then
 result:=result||jsonb_build_object('activity',coalesce((select jsonb_agg(to_jsonb(e) order by e.at desc) from(
 select * from(select 'followup' kind,e.created_at at,e.outcome status,e.note,c.id customer_id,c.full_name customer_name,c.phone from public.jf_followup_events e join public.jf_followups f on f.shop_id=e.shop_id and f.id=e.followup_id join public.jf_customers c on c.shop_id=f.shop_id and c.id=f.customer_id where e.shop_id=target_shop and e.actor_id=(select user_id from public.jf_memberships where id=target_agent) and (report_start is null or e.created_at>=report_start) and (report_end is null or e.created_at<report_end) order by e.created_at desc limit 30) f
 union all
 select * from(select 'order' kind,e.created_at at,e.status,e.note,o.customer_id,o.recipient_name customer_name,o.recipient_phone phone from public.jf_order_events e join public.jf_orders o on o.shop_id=e.shop_id and o.id=e.order_id where e.shop_id=target_shop and e.actor_id=(select user_id from public.jf_memberships where id=target_agent) and (report_start is null or e.created_at>=report_start) and (report_end is null or e.created_at<report_end) order by e.created_at desc limit 30) o
 order by at desc limit 30)e),'[]'::jsonb));end if;
 return result;
end $$;

create or replace function public.jf_workspace_tools(target_shop uuid,tool text,details jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb;rid uuid;mid uuid;ids uuid[];agents uuid[];gid uuid;cid uuid;idx integer:=0;n integer;value jsonb;k text;old public.jf_order_finance%rowtype;
begin
 if not jioflow_private.reads_operations(target_shop) then raise exception 'Workspace access required.' using errcode='42501';end if;
 if jsonb_typeof(details)<>'object' then raise exception 'Invalid details.';end if;
 if tool='customer_orders' then
  cid:=(details->>'customer_id')::uuid;
  if not jioflow_private.can_read_customer(target_shop,cid) or not exists(select 1 from public.jf_customers where shop_id=target_shop and id=cid and archived_at is null) then raise exception 'Customer access denied.' using errcode='42501';end if;
  n:=coalesce((details->>'offset')::integer,0);if n<0 then raise exception 'Invalid offset.';end if;
  return coalesce((select jsonb_agg(to_jsonb(t)) from(select id,order_number,status,total,created_at from public.jf_orders where shop_id=target_shop and customer_id=cid and archived_at is null order by created_at desc,id limit 50 offset n)t),'[]');
 elsif tool='load' then
  return jsonb_build_object('settings',coalesce((select s.value from public.jf_workspace_settings s where s.shop_id=target_shop),'{}'),'layout',coalesce((select p.value from public.jf_workspace_preferences p where p.shop_id=target_shop and p.page=details->>'page' order by p.updated_at desc,p.user_id limit 1),'{}'),'groups',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'active',g.active,'members',coalesce((select jsonb_agg(m.membership_id) from public.jf_group_members m where m.shop_id=g.shop_id and m.group_id=g.id),'[]'))) from public.jf_groups g where g.shop_id=target_shop),'[]'));
 elsif tool='save_layout' then
  if not jioflow_private.has_permission(target_shop,'settings') or jioflow_private.agent_member(target_shop) is not null then raise exception 'Layout editing is not permitted.' using errcode='42501';end if;
  if length(coalesce(details->>'page','')) not between 1 and 50 or jsonb_typeof(details->'value') is distinct from 'object' or octet_length((details->'value')::text)>100000 then raise exception 'Invalid layout.';end if;
  insert into public.jf_workspace_preferences(shop_id,user_id,page,value) values(target_shop,auth.uid(),details->>'page',details->'value') on conflict(shop_id,user_id,page) do update set value=excluded.value,updated_at=now();
 elsif tool='save_settings' then
  if not jioflow_private.has_permission(target_shop,'settings') or jioflow_private.agent_member(target_shop) is not null then raise exception 'Settings editing is not permitted.' using errcode='42501';end if;
  value:=details->'value';if jsonb_typeof(value) is distinct from 'object' or octet_length(value::text)>100000 then raise exception 'Invalid settings.';end if;
  for k in select jsonb_object_keys(value) loop if k not in ('inside','outside','currency','statuses','tags','sources','pull_count','pull_sources','return_policy','schedule','hero') then raise exception 'Unsupported setting: %',k;end if;end loop;
  if value?'inside' and ((value->>'inside')::numeric<0 or (value->>'inside')::numeric>999999) or value?'outside' and ((value->>'outside')::numeric<0 or (value->>'outside')::numeric>999999) then raise exception 'Invalid delivery charge.';end if;
  if value?'pull_count' and (value->>'pull_count')::integer not between 1 and 1000 then raise exception 'Set pull count between 1 and 1000 per transaction.';end if;
  foreach k in array array['statuses','tags','sources','pull_sources'] loop if value?k and (jsonb_typeof(value->k)<>'array' or exists(select 1 from jsonb_array_elements(value->k) x where jsonb_typeof(x)<>'string' or length(x#>>'{}') not between 1 and 120)) then raise exception 'Invalid % list.',k;end if;end loop;
  insert into public.jf_workspace_settings(shop_id,value) values(target_shop,value) on conflict(shop_id) do update set value=public.jf_workspace_settings.value||excluded.value,updated_at=now();
 elsif tool in ('save_group','delete_group') then
  if not jioflow_private.manages_shop(target_shop) then raise exception 'User management permission required.' using errcode='42501';end if;
  gid:=nullif(details->>'id','')::uuid;
  if tool='delete_group' then
   delete from public.jf_group_members where shop_id=target_shop and group_id=gid;delete from public.jf_groups where shop_id=target_shop and id=gid;
  else
   if length(trim(coalesce(details->>'name',''))) not between 1 and 120 then raise exception 'Enter a group name.';end if;
   agents:=array(select x::uuid from jsonb_array_elements_text(coalesce(details->'members','[]')) x);
   if exists(select 1 from unnest(agents) a where not exists(select 1 from public.jf_memberships m join public.jf_profiles p on p.id=m.user_id where m.id=a and m.shop_id=target_shop and m.role='agent' and m.status<>'removed' and p.active)) then raise exception 'Choose Agents from this shop.';end if;
   if gid is null then insert into public.jf_groups(shop_id,name) values(target_shop,trim(details->>'name')) returning id into gid;
   else update public.jf_groups set name=trim(details->>'name') where shop_id=target_shop and id=gid;if not found then raise exception 'Group not found.';end if;end if;
   delete from public.jf_group_members where shop_id=target_shop and group_id=gid;
   insert into public.jf_group_members(shop_id,group_id,membership_id) select target_shop,gid,a from unnest(agents) a on conflict do nothing;
  end if;
 elsif tool='distribute' then
  if not jioflow_private.has_permission(target_shop,'assign') or jioflow_private.agent_member(target_shop) is not null then raise exception 'Distribution permission required.' using errcode='42501';end if;
  ids:=array(select x::uuid from jsonb_array_elements_text(coalesce(details->'ids','[]')) x);
  if cardinality(ids)=0 then raise exception 'Select customers first.';end if;
  gid:=nullif(details->>'group_id','')::uuid;mid:=nullif(details->>'membership_id','')::uuid;
  if gid is not null then agents:=array(select m.id from public.jf_group_members gm join public.jf_memberships m on m.id=gm.membership_id join public.jf_profiles p on p.id=m.user_id where gm.shop_id=target_shop and gm.group_id=gid and m.shop_id=target_shop and m.status='active' and m.role='agent' and p.active order by m.id);if cardinality(agents)=0 then raise exception 'This group has no active Agents.';end if;
  elsif mid is not null then
   if not exists(select 1 from public.jf_memberships m join public.jf_profiles p on p.id=m.user_id where m.id=mid and m.shop_id=target_shop and m.status='active' and m.role='agent' and p.active) then raise exception 'Choose an active Agent in this shop.';end if;agents:=array[mid];
  else agents:=array[]::uuid[];end if;
  perform 1 from public.jf_customers c where c.shop_id=target_shop and c.id=any(ids) order by c.id for update;
  if (select count(*) from public.jf_customers c where c.shop_id=target_shop and c.archived_at is null and c.id=any(ids))<>(select count(distinct a) from unnest(ids) a) then raise exception 'A selected customer is unavailable in this shop.';end if;
  for cid in select c.id from public.jf_customers c where c.shop_id=target_shop and c.id=any(ids) order by c.id loop
   mid:=case when cardinality(agents)>0 then agents[1+(idx%cardinality(agents))] end;
   update public.jf_customers set assigned_membership_id=mid,permanent=case when mid is null then false else permanent end,unassignment_tag=coalesce(details->>'tag',''),updated_at=now() where id=cid;idx:=idx+1;
  end loop;
 elsif tool='pull' then
  mid:=jioflow_private.agent_member(target_shop);
  if mid is null or not jioflow_private.has_permission(target_shop,'pull') then raise exception 'Take More Orders is not permitted.' using errcode='42501';end if;
  select s.value into value from public.jf_workspace_settings s where s.shop_id=target_shop;
  n:=coalesce((value->>'pull_count')::integer,20);if n not between 1 and 1000 then raise exception 'Ask Admin to configure pull count.';end if;
  with chosen as(select c.id from public.jf_customers c where c.shop_id=target_shop and c.archived_at is null and c.assigned_membership_id is null and (coalesce(jsonb_array_length(value->'pull_sources'),0)=0 or lower(c.source) in(select lower(jsonb_array_elements_text(value->'pull_sources')))) order by c.updated_at,c.id for update skip locked limit n),updated as(update public.jf_customers c set assigned_membership_id=mid,updated_at=now() from chosen where c.id=chosen.id returning c.id) select count(*) into idx from updated;
 elsif tool='products' then
  if not jioflow_private.has_permission(target_shop,'products') then raise exception 'Product editing is not permitted.' using errcode='42501';end if;
  ids:=array(select x::uuid from jsonb_array_elements_text(coalesce(details->'ids','[]')) x);if cardinality(ids)=0 then raise exception 'Select products first.';end if;
  if details->>'action' not in ('activate','deactivate','archive','restore','feature','unfeature') then raise exception 'Invalid product action.';end if;
  update public.jf_products set featured=case when details->>'action'='feature' then true when details->>'action'='unfeature' then false else featured end,active=case when details->>'action'='activate' then true when details->>'action'='deactivate' then false else active end,archived_at=case when details->>'action'='archive' then now() when details->>'action'='restore' then null else archived_at end,updated_at=now() where shop_id=target_shop and id=any(ids);get diagnostics idx=row_count;
 elsif tool='customer_labels' then
  cid:=(details->>'customer_id')::uuid;
  if not jioflow_private.has_permission(target_shop,'assign') or not jioflow_private.can_read_customer(target_shop,cid) then raise exception 'Customer editing is not permitted.' using errcode='42501';end if;
  if length(coalesce(details->>'label',''))>120 or length(coalesce(details->>'tag',''))>120 then raise exception 'Label or tag too long.';end if;
  update public.jf_customers set workflow_label=coalesce(details->>'label',''),unassignment_tag=coalesce(details->>'tag',''),updated_at=now() where shop_id=target_shop and id=cid and archived_at is null;
 elsif tool='save_finance' then
  if not jioflow_private.has_permission(target_shop,'profit') then raise exception 'Finance permission required.' using errcode='42501';end if;
  rid:=(details->>'order_id')::uuid;
  perform 1 from public.jf_orders where id=rid and shop_id=target_shop and archived_at is null for update;if not found then raise exception 'Order not found.';end if;
  select * into old from public.jf_order_finance where shop_id=target_shop and order_id=rid;
  foreach k in array array['product_cost','courier_charge','cod_fee','packaging_cost','return_cost','other_cost','cod_expected','cod_received'] loop if not details?k or (details->>k)::numeric<0 or (details->>k)::numeric>999999999999.99 then raise exception 'Check %.',k;end if;end loop;
  insert into public.jf_order_finance(shop_id,order_id,product_cost,courier_charge,cod_fee,packaging_cost,return_cost,other_cost,cod_expected,cod_received) values(target_shop,rid,(details->>'product_cost')::numeric,(details->>'courier_charge')::numeric,(details->>'cod_fee')::numeric,(details->>'packaging_cost')::numeric,(details->>'return_cost')::numeric,(details->>'other_cost')::numeric,(details->>'cod_expected')::numeric,(details->>'cod_received')::numeric)
  on conflict(order_id) do update set product_cost=excluded.product_cost,courier_charge=excluded.courier_charge,cod_fee=excluded.cod_fee,packaging_cost=excluded.packaging_cost,return_cost=excluded.return_cost,other_cost=excluded.other_cost,cod_expected=excluded.cod_expected,cod_received=excluded.cod_received,updated_at=now();
 else raise exception 'Unknown workspace tool.';end if;
 insert into jioflow_private.account_audit(actor_id,target_id,action,details) values(auth.uid(),auth.uid(),'workspace_'||tool,jsonb_build_object('shop_id',target_shop,'count',idx,'record_id',coalesce(rid,gid,cid)));
 return jsonb_build_object('saved',true,'id',coalesce(rid,gid,cid),'count',idx);
end $$;
insert into public.jf_schema_versions(version) values('029_shared_live_workflow') on conflict do nothing;
commit;


-- Full pre-booking recipient editing, with existing status/tenant/courier locks.
begin;
do $$begin if not exists(select 1 from public.jf_schema_versions where version='029_shared_live_workflow') then raise exception 'Apply migration 029 first.';end if;end$$;
create or replace function public.jf_edit_order_details(target_shop uuid,target_order uuid,details jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare patch jsonb:='{}';k text;normalized text;old public.jf_orders%rowtype;
begin
 if jsonb_typeof(details) is distinct from 'object' or exists(select 1 from jsonb_object_keys(details) as keys(field_name) where keys.field_name not in('recipient_name','recipient_phone','delivery_address','area','source','status','note','assigned_membership_id')) then raise exception 'Unsupported order field.';end if;
 for k in select jsonb_object_keys(details) loop if k in('status','note','assigned_membership_id') then patch:=patch||jsonb_build_object(k,details->k);end if;end loop;
 -- This performs permission, session, order visibility, status, assignment and courier lease checks.
 perform public.jf_update_order(target_shop,target_order,patch);
 select * into old from public.jf_orders where shop_id=target_shop and id=target_order for update;
 if details?'recipient_name' and length(trim(coalesce(details->>'recipient_name',''))) not between 1 and 200 then raise exception 'Enter a customer name.';end if;
 if details?'delivery_address' and length(trim(coalesce(details->>'delivery_address',''))) not between 1 and 2000 then raise exception 'Enter a delivery address.';end if;
 if length(coalesce(details->>'area',''))>200 or length(coalesce(details->>'source',''))>100 then raise exception 'Area or source is too long.';end if;
 normalized:=case when details?'recipient_phone' then jioflow_private.normalize_phone(details->>'recipient_phone') else old.recipient_phone end;
 update public.jf_orders set recipient_name=coalesce(trim(details->>'recipient_name'),recipient_name),recipient_phone=normalized,delivery_address=coalesce(trim(details->>'delivery_address'),delivery_address),area=coalesce(details->>'area',area),source=coalesce(details->>'source',source),updated_at=now() where shop_id=target_shop and id=target_order;
 return target_order;
end$$;
revoke all on function public.jf_edit_order_details(uuid,uuid,jsonb) from public,anon;
grant execute on function public.jf_edit_order_details(uuid,uuid,jsonb) to authenticated;
insert into public.jf_schema_versions(version) values('030_order_recipient_edit') on conflict do nothing;
commit;
